  ('brown', 'Dr Brown', false, 'ექიმი კლინიკაში', '{"skin":"#E9C3A2","hair":"#B9BEC6","style":"short","shirt":"#E8F1F8","bg":"#1E2B33"}'::jsonb)
insert into public.sections (id, position, cefr, name_ka, description_ka, is_locked) values
  ('s1', 1, 'A1', 'დამწყები', 'პირველი ნაბიჯები: გაცნობა, კაფე, სასტუმრო და ქალაქში გადაადგილება.', false),
  ('s2', 2, 'A2', 'საბაზისო', 'მოგზაურობის რეალური სიტუაციები: რესტორანი, მაღაზია, აეროპორტი, ექიმი.', false),
  ('s3', 3, 'B1', 'საშუალო', 'თავისუფალი საუბარი, სამსახური და ტელეფონით კომუნიკაცია.', true),
  ('s4', 4, 'B2', 'საშუალოზე მაღალი', 'სამუშაო შეხვედრები, აზრის გამოხატვა და მოლაპარაკება.', true)
insert into public.units (id, section_id, position, title_en, title_ka, tip_ka, short_tip_ka, scene_ka, host_id, partner_id, grammar, sound_tip_ka, note_ka) values
  ('u1', 's1', 1, 'Meeting people', 'გაცნობა და მისალმება', 'ინგლისურ წინადადებას ყოველთვის სჭირდება ზმნა. „ვარ“ = I am, „ხარ / ხართ“ = you are. ქართულში ხშირად ზმნას ვტოვებთ, ინგლისურში კი არასდროს: სწორია „I am fine“ და არა „I fine“.', 'ინგლისურში ზმნა არ გამოიტოვება: I am fine.', 'ნინო ენების გაცვლის საღამოზეა და ტომს ეცნობა.', 'nino', 'tom', '{"title":"ზმნა to be: am / is / are","explanation":"I am (მე ვარ), you are (შენ ხარ / თქვენ ხართ), he / she is (ის არის). ქართულად ხშირად ვამბობთ უბრალოდ „კარგად“, ინგლისურად კი ზმნა აუცილებელია.","examples":[{"en":"I am Nino.","ka":"მე ნინო ვარ."},{"en":"You are my friend.","ka":"შენ ჩემი მეგობარი ხარ."},{"en":"She is from Tbilisi.","ka":"ის თბილისიდანაა."}]}'::jsonb, 'th სიტყვაში thank you ქართული „თ“ არ არის: ენის წვერი ოდნავ კბილებს შორის მოათავსე და ჰაერი ნაზად გაუშვი.', 'you ნიშნავს „შენ“-საც და „თქვენ“-საც. თავაზიანობას ინგლისურში ტონი და სიტყვები please და thank you გამოხატავს.'),
  ('u2', 's1', 2, 'At the café', 'კაფეში', 'ქართულში არტიკლი არ გვაქვს. ინგლისურში ერთი საგნის წინ ვამბობთ a-ს: a coffee, a cake. თუ სიტყვა ხმოვანი ბგერით იწყება, ვამბობთ an-ს: an apple. სიტყვა please თხოვნას თავაზიანს ხდის.', 'ერთი საგნის წინ ვამბობთ a-ს: a coffee, a cake.', 'გიორგი ლონდონის კაფეში ყავას უკვეთავს. ბარისტა ემაა.', 'giorgi', 'emma', '{"title":"a / an: ერთი რაღაც","explanation":"ერთი, დასათვლელი საგნის წინ ვამბობთ a-ს. თუ სიტყვა ხმოვანი ბგერით იწყება, ვამბობთ an-ს. ქართულს არტიკლი არ აქვს, ამიტომ მისი დავიწყება ძალიან ხშირი შეცდომაა.","examples":[{"en":"a coffee","ka":"ერთი ყავა"},{"en":"an apple","ka":"ერთი ვაშლი"},{"en":"a glass of water","ka":"ერთი ჭიქა წყალი"}]}'::jsonb, 'water ამერიკულად ჟღერს დაახლოებით „უოდერ“, ბრიტანულად „უოტა“. ორივე სწორია.', 'ბრიტანეთის კაფეებში ხშირად გკითხავენ: For here or to go? ანუ აქ დალევთ თუ თან წაიღებთ.'),
  ('u3', 's1', 3, 'Hotel check-in', 'სასტუმროში', 'Can I have…? ყველაზე მარტივი და თავაზიანი თხოვნაა სასტუმროში, კაფეში თუ მაღაზიაში. პასუხად ხშირად გაიგებთ: Sure! ან Of course!', 'Can I have…? თავაზიანი თხოვნაა.', 'თამარი კონფერენციაზე ჩავიდა და სასტუმროში რეგისტრირდება.', 'tamar', 'james', '{"title":"Can I have…? თავაზიანი თხოვნა","explanation":"Can I have + საგანი? ასე ითხოვენ თითქმის ყველაფერს: გასაღებს, პირსახოცს, ანგარიშს. უფრო ოფიციალურად: Could I have…?","examples":[{"en":"Can I have another key?","ka":"შეიძლება კიდევ ერთი გასაღები?"},{"en":"Could I have a towel?","ka":"შეიძლება პირსახოცი?"},{"en":"Can I have the Wi-Fi password?","ka":"შეიძლება Wi-Fi-ს პაროლი?"}]}'::jsonb, 'room გამოითქმის გრძელი „უუ“-თი: „რუუმ“. key კი გრძელი „ი“-თი: „ქიი“.', 'ოთახის ნომერს ციფრებად ამბობენ: Room 305 ჟღერს როგორც „three-oh-five“.'),
  ('u4', 's1', 4, 'Getting around', 'ქალაქში გადაადგილება', 'კითხვა „სად არის…?“ ინგლისურად იწყება Where is…-ით. კითხვაში ზმნა is ქვემდებარის წინ გადადის: The station is near → Where is the station?', 'კითხვაში is წინ გადადის: Where is the station?', 'ლუკა პირველად არის ლონდონში და მეტროს სადგურს ეძებს.', 'luka', 'kate', '{"title":"კითხვა Where is…?","explanation":"კითხვაში is ქვემდებარის წინ გადადის. მრავლობითში is-ის ნაცვლად ვამბობთ are-ს: Where are the taxis?","examples":[{"en":"The station is near.","ka":"სადგური ახლოსაა."},{"en":"Where is the station?","ka":"სად არის სადგური?"},{"en":"Where are the toilets?","ka":"სად არის ტუალეტები?"}]}'::jsonb, 'left და right: l-ის დროს ენის წვერი ზემო კბილებს ეხება, r-ის დროს ენა არაფერს ეხება და არ ცახცახებს.', 'ლონდონში მეტროს the Underground ან the Tube ჰქვია, ნიუ-იორკში კი the subway.'),
  ('u5', 's2', 1, 'At the restaurant', 'რესტორანში', 'შეკვეთისას ამბობენ I''ll have… (= I will have) ან I''d like… (= I would like). ორივე გაცილებით თავაზიანად ჟღერს, ვიდრე I want.', 'შეკვეთისას ამბობენ I''ll have… ან I''d like…', 'ნინო და გიორგი რესტორანში ვახშმობენ. მიმტანი დევიდია.', 'nino', 'david', '{"title":"I''ll have… / I''d like…: შეკვეთა","explanation":"I''ll = I will, I''d = I would. რესტორანში I want-ის ნაცვლად სწორედ ამ ფორმებს იყენებენ.","examples":[{"en":"I''ll have the soup.","ka":"სუპს ავიღებ."},{"en":"I''d like a salad.","ka":"სალათი მინდა."},{"en":"We''d like some water.","ka":"ცოტა წყალი გვინდა."}]}'::jsonb, 'bill გამოითქმის მოკლე „ი“-თი: „ბილ“. გრძელი „ი“ (beel) სხვა სიტყვად ჟღერს.', 'ანგარიშის წინ იკითხე Is service included? ხშირად ჩაის ფული (tip) უკვე შედის ფასში.'),
  ('u6', 's2', 2, 'Shopping', 'საყიდლებზე', 'too და very სხვადასხვაა: very expensive = ძალიან ძვირი, too expensive = ზედმეტად ძვირი (ანუ არ ვყიდულობ). შედარებისას: small → smaller, big → bigger.', 'too expensive ნიშნავს ზედმეტად ძვირს.', 'მარიამი ახალ პერანგს ყიდულობს. გამყიდველი ლუსია.', 'mariam', 'lucy', '{"title":"too და very; smaller, bigger","explanation":"very = ძალიან, too = ზედმეტად (ანუ არ გამომადგება). შედარებისას მოკლე სიტყვებს ემატება -er: small → smaller, cheap → cheaper. გრძელ სიტყვებთან: more expensive.","examples":[{"en":"It is very nice.","ka":"ძალიან ლამაზია."},{"en":"It is too big.","ka":"ზედმეტად დიდია."},{"en":"Do you have a cheaper one?","ka":"უფრო იაფი გაქვთ?"}]}'::jsonb, 'shirt და shoes იწყება ბგერით sh, რომელიც ქართულ „შ“-ს ჰგავს.', 'ტანსაცმლის ზომები ქვეყნების მიხედვით განსხვავდება. მოზომვამდე იკითხე: Can I try it on?'),
  ('u7', 's2', 3, 'At the airport', 'აეროპორტში', 'აეროპორტში ხშირად გაიგებთ ფორმას am / is / are + ზმნა-ing: Boarding is starting now, the plane is leaving. ეს ნიშნავს, რომ მოქმედება ახლა ხდება.', 'am / is / are + -ing ნიშნავს ახლა მიმდინარე მოქმედებას.', 'გიორგი სახლში ბრუნდება და აეროპორტში რეგისტრაციას გადის.', 'giorgi', 'anna', '{"title":"am / is / are + -ing: ახლა მიმდინარე","explanation":"როცა მოქმედება ახლა ხდება, ვამბობთ am / is / are + ზმნა-ing: The plane is leaving. აეროპორტის განცხადებებში ამ ფორმას ხშირად გაიგებ.","examples":[{"en":"Boarding is starting now.","ka":"ჩასხდომა ახლა იწყება."},{"en":"I am waiting at gate twelve.","ka":"მეთორმეტე გასასვლელთან ველოდები."},{"en":"We are flying to Tbilisi.","ka":"თბილისში მივფრინავთ."}]}'::jsonb, 'luggage გამოითქმის დაახლოებით „ლაგიჯ“: ბოლოში ჟღერს „ჯ“ და არა „გე“.', 'check in ნიშნავს რეგისტრაციას და ბარგის ჩაბარებას, boarding კი თვითმფრინავში ჩასხდომას.'),
  ('u8', 's2', 4, 'Doctor & pharmacy', 'ექიმთან და აფთიაქში', 'ქართულად ვამბობთ „თავი მტკივა“, ინგლისურად კი ტკივილი „გვაქვს“: I have a headache, I have a fever. ზოგადად ტკივილზე: It hurts here.', 'ინგლისურად ტკივილი „გვაქვს“: I have a headache.', 'თამარი მოგზაურობისას შეუძლოდ გახდა და ექიმთან მივიდა.', 'tamar', 'brown', '{"title":"I have a…: ტკივილი და სიმპტომები","explanation":"ქართულად ვამბობთ „თავი მტკივა“, ინგლისურად კი ტკივილი „გვაქვს“: I have a headache. კონკრეტულ ადგილზე: It hurts here ან My back hurts.","examples":[{"en":"I have a headache.","ka":"თავი მტკივა."},{"en":"I have a cold.","ka":"გაციებული ვარ."},{"en":"My back hurts.","ka":"ზურგი მტკივა."}]}'::jsonb, 'headache-ში ch იკითხება როგორც „კ“: „ჰედეიკ“.', 'საგანგებო ნომერი ევროპის ქვეყნებში 112-ია, აშშ-ში 911, დიდ ბრიტანეთში 999 (112-იც მუშაობს).')
insert into public.vocab_items (id, unit_id, position, en, ka, phonetic, image_key) values
  ('u1.v1', 'u1', 1, 'hello', 'გამარჯობა', '/həˈloʊ/', 'waving'),
