  ('u1.v3', 'u1', 3, 'please', 'გთხოვთ', '/pliːz/', 'palms'),
  ('u1.v4', 'u1', 4, 'goodbye', 'ნახვამდის', '/ɡʊdˈbaɪ/', 'walking'),
  ('u1.v5', 'u1', 5, 'name', 'სახელი', '/neɪm/', 'label'),
  ('u1.v6', 'u1', 6, 'friend', 'მეგობარი', '/frɛnd/', 'handshake'),
  ('u2.v1', 'u2', 1, 'coffee', 'ყავა', '/ˈkɔː.fi/', 'coffee'),
  ('u2.v2', 'u2', 2, 'tea', 'ჩაი', '/tiː/', 'tea'),
  ('u2.v3', 'u2', 3, 'water', 'წყალი', '/ˈwɔː.tər/', 'droplet'),
  ('u2.v4', 'u2', 4, 'sugar', 'შაქარი', '/ˈʃʊɡ.ər/', 'candy'),
  ('u2.v5', 'u2', 5, 'milk', 'რძე', '/mɪlk/', 'milk'),
  ('u2.v6', 'u2', 6, 'cake', 'ნამცხვარი', '/keɪk/', 'cake'),
