  ('u7.v1', 'u7', 1, 'flight', 'რეისი', '/flaɪt/', 'airplane'),
  ('u7.v2', 'u7', 2, 'gate', 'გასასვლელი', '/ɡeɪt/', 'door'),
  ('u7.v3', 'u7', 3, 'luggage', 'ბარგი', '/ˈlʌɡ.ɪdʒ/', 'luggage'),
