insert into public.phrases (id, unit_id, position, en, ka) values
  ('u1.p1', 'u1', 1, 'Hello, my name is Nino.', 'გამარჯობა, მე ნინო მქვია.'),
  ('u1.p2', 'u1', 2, 'Nice to meet you.', 'სასიამოვნოა თქვენი გაცნობა.'),
  ('u1.p3', 'u1', 3, 'How are you?', 'როგორ ხართ?'),
  ('u1.p4', 'u1', 4, 'I am fine, thank you.', 'კარგად ვარ, გმადლობთ.'),
  ('u1.p5', 'u1', 5, 'Where are you from?', 'საიდან ხართ?'),
  ('u1.p6', 'u1', 6, 'I am from Georgia.', 'მე საქართველოდან ვარ.'),
  ('u1.p7', 'u1', 7, 'What is your name?', 'რა გქვიათ?'),
  ('u1.p8', 'u1', 8, 'See you tomorrow.', 'ხვალამდე.'),
  ('u2.p1', 'u2', 1, 'A coffee, please.', 'ერთი ყავა, თუ შეიძლება.'),
  ('u2.p2', 'u2', 2, 'Can I have a tea with milk?', 'შეიძლება ჩაი რძით?'),
  ('u2.p3', 'u2', 3, 'How much is it?', 'რა ღირს?'),
  ('u2.p4', 'u2', 4, 'I would like a glass of water.', 'ერთი ჭიქა წყალი მინდა.'),
  ('u2.p5', 'u2', 5, 'Without sugar, please.', 'შაქრის გარეშე, თუ შეიძლება.'),
  ('u2.p6', 'u2', 6, 'Can I pay by card?', 'შეიძლება ბარათით გადავიხადო?'),
  ('u2.p7', 'u2', 7, 'To go, please.', 'წასაღებად, თუ შეიძლება.'),
  ('u2.p8', 'u2', 8, 'The cake is delicious.', 'ნამცხვარი გემრიელია.'),
  ('u3.p1', 'u3', 1, 'I have a reservation.', 'ოთახი დაჯავშნილი მაქვს.'),
  ('u3.p2', 'u3', 2, 'For three nights.', 'სამი ღამით.'),
  ('u3.p3', 'u3', 3, 'What time is breakfast?', 'რომელ საათზეა საუზმე?'),
  ('u3.p4', 'u3', 4, 'Here is my passport.', 'აი, ჩემი პასპორტი.'),
  ('u3.p5', 'u3', 5, 'Is the Wi-Fi free?', 'Wi-Fi უფასოა?'),
  ('u3.p6', 'u3', 6, 'The room is too cold.', 'ოთახში ძალიან ცივა.'),
  ('u3.p7', 'u3', 7, 'Can I have another key?', 'შეიძლება კიდევ ერთი გასაღები?'),
  ('u3.p8', 'u3', 8, 'What time is check-out?', 'რომელ საათზეა ნომრის დატოვება?'),
  ('u4.p1', 'u4', 1, 'Where is the metro station?', 'სად არის მეტროს სადგური?'),
  ('u4.p2', 'u4', 2, 'Turn left at the corner.', 'კუთხეში მოუხვიეთ მარცხნივ.'),
  ('u4.p3', 'u4', 3, 'Go straight ahead.', 'პირდაპირ იარეთ.'),
  ('u4.p4', 'u4', 4, 'How far is it?', 'რამდენად შორსაა?'),
  ('u4.p5', 'u4', 5, 'One ticket to Batumi, please.', 'ერთი ბილეთი ბათუმამდე, თუ შეიძლება.'),
  ('u4.p6', 'u4', 6, 'Can you call a taxi?', 'შეგიძლიათ ტაქსი გამოიძახოთ?'),
  ('u4.p7', 'u4', 7, 'Stop here, please.', 'აქ გამიჩერეთ, თუ შეიძლება.'),
  ('u4.p8', 'u4', 8, 'I am lost.', 'გზა ამებნა.'),
  ('u5.p1', 'u5', 1, 'A table for two, please.', 'მაგიდა ორისთვის, თუ შეიძლება.'),
  ('u5.p2', 'u5', 2, 'Can we see the menu?', 'შეიძლება მენიუ ვნახოთ?'),
  ('u5.p3', 'u5', 3, 'What do you recommend?', 'რას გვირჩევთ?'),
  ('u5.p4', 'u5', 4, 'I am allergic to fish.', 'თევზზე ალერგია მაქვს.'),
  ('u5.p5', 'u5', 5, 'I will have the soup.', 'სუპს ავიღებ.'),
  ('u5.p6', 'u5', 6, 'Could we have the bill, please?', 'ანგარიში მოგვიტანეთ, თუ შეიძლება.'),
  ('u5.p7', 'u5', 7, 'Is service included?', 'მომსახურება ფასში შედის?'),
  ('u5.p8', 'u5', 8, 'Everything was delicious.', 'ყველაფერი გემრიელი იყო.'),
  ('u6.p1', 'u6', 1, 'How much does this cost?', 'ეს რა ღირს?'),
  ('u6.p2', 'u6', 2, 'Do you have a smaller size?', 'უფრო პატარა ზომა გაქვთ?'),
  ('u6.p3', 'u6', 3, 'Can I try it on?', 'შეიძლება მოვიზომო?'),
  ('u6.p4', 'u6', 4, 'It is too expensive.', 'ზედმეტად ძვირია.'),
  ('u6.p5', 'u6', 5, 'I am just looking.', 'უბრალოდ ვათვალიერებ.'),
  ('u6.p6', 'u6', 6, 'Where is the fitting room?', 'სად არის გასახდელი?'),
  ('u6.p7', 'u6', 7, 'I will take it.', 'ამას ავიღებ.'),
  ('u6.p8', 'u6', 8, 'Do you have it in black?', 'შავი ფერის გაქვთ?'),
  ('u7.p1', 'u7', 1, 'Where is gate twelve?', 'სად არის მეთორმეტე გასასვლელი?'),
  ('u7.p2', 'u7', 2, 'My flight is delayed.', 'ჩემი რეისი იგვიანებს.'),
  ('u7.p3', 'u7', 3, 'I have one bag to check in.', 'ერთი ჩანთა მაქვს ჩასაბარებელი.'),
  ('u7.p4', 'u7', 4, 'Can I have a window seat?', 'შეიძლება ფანჯარასთან ადგილი?'),
  ('u7.p5', 'u7', 5, 'My luggage is lost.', 'ჩემი ბარგი დაიკარგა.'),
  ('u7.p6', 'u7', 6, 'When does boarding start?', 'როდის იწყება ჩასხდომა?'),
  ('u7.p7', 'u7', 7, 'I am here on holiday.', 'აქ დასასვენებლად ვარ.'),
  ('u7.p8', 'u7', 8, 'How long is the flight?', 'რამდენ ხანს გრძელდება ფრენა?'),
  ('u8.p1', 'u8', 1, 'I need a doctor.', 'ექიმი მჭირდება.'),
  ('u8.p2', 'u8', 2, 'I have a headache.', 'თავი მტკივა.'),
  ('u8.p3', 'u8', 3, 'I have a fever.', 'სიცხე მაქვს.'),
  ('u8.p4', 'u8', 4, 'Where is the nearest pharmacy?', 'სად არის უახლოესი აფთიაქი?'),
  ('u8.p5', 'u8', 5, 'How often should I take this?', 'რამდენად ხშირად უნდა მივიღო ეს?'),
  ('u8.p6', 'u8', 6, 'It hurts here.', 'აქ მტკივა.'),
  ('u8.p7', 'u8', 7, 'Do I need a prescription?', 'რეცეპტი მჭირდება?'),
  ('u8.p8', 'u8', 8, 'I feel much better.', 'ბევრად უკეთ ვგრძნობ თავს.')
insert into public.dialog_lines (id, unit_id, position, speaker_id, en, ka) values
  ('u1.d1', 'u1', 1, 'tom', 'Hi! I''m Tom. What is your name?', 'გამარჯობა! მე ტომი ვარ. რა გქვია?'),
  ('u1.d2', 'u1', 2, 'nino', 'Hello, my name is Nino. Nice to meet you.', 'გამარჯობა, მე ნინო მქვია. სასიამოვნოა შენი გაცნობა.'),
  ('u1.d3', 'u1', 3, 'tom', 'Nice to meet you too. Where are you from?', 'მეც სასიამოვნოა. საიდან ხარ?'),
  ('u1.d4', 'u1', 4, 'nino', 'I am from Georgia. And you?', 'საქართველოდან ვარ. შენ?'),
  ('u1.d5', 'u1', 5, 'tom', 'I am from London. How are you today?', 'ლონდონიდან. როგორ ხარ დღეს?'),
  ('u1.d6', 'u1', 6, 'nino', 'I am fine, thank you. See you tomorrow!', 'კარგად ვარ, გმადლობ. ხვალამდე!'),
  ('u2.d1', 'u2', 1, 'emma', 'Hi! What can I get you?', 'გამარჯობა! რას მიირთმევთ?'),
  ('u2.d2', 'u2', 2, 'giorgi', 'A coffee, please. Without sugar.', 'ერთი ყავა, თუ შეიძლება. შაქრის გარეშე.'),
  ('u2.d3', 'u2', 3, 'emma', 'Sure. For here or to go?', 'რა თქმა უნდა. აქ დალევთ თუ წაიღებთ?'),
  ('u2.d4', 'u2', 4, 'giorgi', 'To go, please. How much is it?', 'წასაღებად, თუ შეიძლება. რა ღირს?'),
  ('u2.d5', 'u2', 5, 'emma', 'Three pounds fifty.', 'სამი ფუნტი და ორმოცდაათი პენსი.'),
  ('u2.d6', 'u2', 6, 'giorgi', 'Can I pay by card?', 'შეიძლება ბარათით გადავიხადო?'),
  ('u3.d1', 'u3', 1, 'james', 'Good evening! How can I help you?', 'საღამო მშვიდობისა! რით შემიძლია დაგეხმაროთ?'),
  ('u3.d2', 'u3', 2, 'tamar', 'Hello, I have a reservation.', 'გამარჯობა, ოთახი დაჯავშნილი მაქვს.'),
  ('u3.d3', 'u3', 3, 'james', 'What is your name, please?', 'თქვენი სახელი, თუ შეიძლება?'),
  ('u3.d4', 'u3', 4, 'tamar', 'Tamar Beridze. For three nights.', 'თამარ ბერიძე. სამი ღამით.'),
  ('u3.d5', 'u3', 5, 'james', 'Here is your key. Room 305.', 'აი, თქვენი გასაღები. ოთახი 305.'),
  ('u3.d6', 'u3', 6, 'tamar', 'Thank you. What time is breakfast?', 'გმადლობთ. რომელ საათზეა საუზმე?'),
  ('u4.d1', 'u4', 1, 'luka', 'Excuse me, where is the metro station?', 'ბოდიში, სად არის მეტროს სადგური?'),
  ('u4.d2', 'u4', 2, 'kate', 'Go straight ahead and turn left at the corner.', 'პირდაპირ იარეთ და კუთხეში მოუხვიეთ მარცხნივ.'),
  ('u4.d3', 'u4', 3, 'luka', 'How far is it?', 'რამდენად შორსაა?'),
  ('u4.d4', 'u4', 4, 'kate', 'About five minutes on foot.', 'ფეხით დაახლოებით ხუთი წუთია.'),
  ('u4.d5', 'u4', 5, 'luka', 'Thank you very much!', 'დიდი მადლობა!'),
  ('u4.d6', 'u4', 6, 'kate', 'You''re welcome. Have a nice day!', 'არაფრის. კარგ დღეს გისურვებთ!'),
  ('u5.d1', 'u5', 1, 'david', 'Good evening. A table for two?', 'საღამო მშვიდობისა. მაგიდა ორისთვის?'),
  ('u5.d2', 'u5', 2, 'nino', 'Yes, please. Can we see the menu?', 'დიახ. შეიძლება მენიუ ვნახოთ?'),
  ('u5.d3', 'u5', 3, 'david', 'Of course. Are you ready to order?', 'რა თქმა უნდა. მზად ხართ შესაკვეთად?'),
  ('u5.d4', 'u5', 4, 'nino', 'I will have the soup. I am allergic to fish.', 'სუპს ავიღებ. თევზზე ალერგია მაქვს.'),
  ('u5.d5', 'u5', 5, 'david', 'No problem. Anything to drink?', 'პრობლემა არაა. დასალევად რას ინებებთ?'),
  ('u5.d6', 'u5', 6, 'nino', 'Just water, please.', 'მხოლოდ წყალი, თუ შეიძლება.'),
  ('u6.d1', 'u6', 1, 'lucy', 'Hi! Can I help you?', 'გამარჯობა! შემიძლია დაგეხმაროთ?'),
  ('u6.d2', 'u6', 2, 'mariam', 'I am just looking, thanks.', 'უბრალოდ ვათვალიერებ, მადლობა.'),
  ('u6.d3', 'u6', 3, 'lucy', 'Sure. Let me know if you need anything.', 'კარგი. თუ რამე დაგჭირდებათ, მითხარით.'),
  ('u6.d4', 'u6', 4, 'mariam', 'Do you have a smaller size?', 'უფრო პატარა ზომა გაქვთ?'),
  ('u6.d5', 'u6', 5, 'lucy', 'Yes, here you are. The fitting room is over there.', 'დიახ, ინებეთ. გასახდელი იქაა.'),
  ('u6.d6', 'u6', 6, 'mariam', 'Thank you. I will take it!', 'გმადლობთ. ამას ავიღებ!'),
  ('u7.d1', 'u7', 1, 'anna', 'Good morning. Your passport, please.', 'დილა მშვიდობისა. თქვენი პასპორტი, თუ შეიძლება.'),
  ('u7.d2', 'u7', 2, 'giorgi', 'Here you are. I have one bag to check in.', 'ინებეთ. ერთი ჩანთა მაქვს ჩასაბარებელი.'),
  ('u7.d3', 'u7', 3, 'anna', 'Would you like a window seat or an aisle seat?', 'ფანჯარასთან ადგილი გნებავთ თუ გასასვლელთან?'),
  ('u7.d4', 'u7', 4, 'giorgi', 'A window seat, please. When does boarding start?', 'ფანჯარასთან, თუ შეიძლება. როდის იწყება ჩასხდომა?'),
  ('u7.d5', 'u7', 5, 'anna', 'At ten thirty. Gate twelve.', '10:30-ზე. მეთორმეტე გასასვლელი.'),
  ('u7.d6', 'u7', 6, 'giorgi', 'Thank you. Is the flight on time?', 'გმადლობთ. რეისი დროზეა?'),
  ('u8.d1', 'u8', 1, 'brown', 'Hello. What seems to be the problem?', 'გამარჯობა. რა გაწუხებთ?'),
  ('u8.d2', 'u8', 2, 'tamar', 'I have a headache and a fever.', 'თავი მტკივა და სიცხე მაქვს.'),
  ('u8.d3', 'u8', 3, 'brown', 'How long have you had it?', 'რამდენი ხანია, რაც ასე ხართ?'),
  ('u8.d4', 'u8', 4, 'tamar', 'Since yesterday.', 'გუშინდლიდან.'),
  ('u8.d5', 'u8', 5, 'brown', 'Take this medicine twice a day.', 'ეს წამალი დღეში ორჯერ მიიღეთ.'),
