insert into public.common_mistakes (id, unit_id, position, wrong, correct, note_ka) values
  ('u1.m1', 'u1', 1, 'I fine.', 'I am fine.', 'ზმნა am არ გამოტოვო.'),
  ('u1.m2', 'u1', 2, 'My name Nino.', 'My name is Nino.', 'name-ის შემდეგ საჭიროა is.'),
  ('u2.m1', 'u2', 1, 'I want coffee.', 'I would like a coffee, please.', 'I want უხეშად ჟღერს, I would like თავაზიანია.'),
  ('u2.m2', 'u2', 2, 'Give me tea.', 'Can I have a tea, please?', 'თხოვნა კითხვის ფორმით უფრო ბუნებრივია.'),
  ('u3.m1', 'u3', 1, 'I have reservation.', 'I have a reservation.', 'reservation-ის წინ a სჭირდება.'),
  ('u3.m2', 'u3', 2, 'For three night.', 'For three nights.', 'ერთზე მეტის შემთხვევაში სიტყვას -s ემატება.'),
  ('u4.m1', 'u4', 1, 'Where the station is?', 'Where is the station?', 'კითხვაში is წინ მოდის.'),
  ('u4.m2', 'u4', 2, 'Where is metro?', 'Where is the metro?', 'კონკრეტული ადგილის წინ ვამბობთ the-ს.'),
  ('u5.m1', 'u5', 1, 'Bring me the bill.', 'Could we have the bill, please?', 'ბრძანებითი ფორმა უხეშად ჟღერს.'),
  ('u5.m2', 'u5', 2, 'I am allergy to fish.', 'I am allergic to fish.', 'allergy არსებითი სახელია, allergic ზედსართავი.'),
  ('u6.m1', 'u6', 1, 'It is more cheap.', 'It is cheaper.', 'მოკლე ზედსართავს -er ემატება.'),
  ('u6.m2', 'u6', 2, 'How much it costs?', 'How much does it cost?', 'კითხვაში საჭიროა does.'),
  ('u7.m1', 'u7', 1, 'My flight delayed.', 'My flight is delayed.', 'is აუცილებელია.'),
  ('u7.m2', 'u7', 2, 'I am go to London.', 'I am going to London.', 'am-ის შემდეგ ზმნას ემატება -ing.'),
  ('u8.m1', 'u8', 1, 'My head is hurt.', 'My head hurts.', 'hurts თავად ზმნაა, is არ სჭირდება.'),
  ('u8.m2', 'u8', 2, 'I have temperature.', 'I have a fever.', 'სიცხეზე ამბობენ a fever ან a temperature.')
